// Exports M2 time and recurrence goldens from the TS code:
//   internal/zone/names_gen.go  the zone names Intl accepts (case folded) and the
//                                short names luxon prints that aren't "GMT+H"
//   testdata/time.json           cases for reminders/time.ts, parse.ts's
//                                todayInstead (through finishParse) and the
//                                luxon day math budget uses
//
// The zone list is Go's own (time/tzdata), so the generated table never names a
// zone the Go binary can't load. Run from apps/app:
//   unzip -Z1 "$(go list -f '{{.Dir}}' time)/../../lib/time/zoneinfo.zip" > /tmp/go-zones.txt
//   cd apps/app && pnpm tsx ../server/testdata/gen/time.ts /tmp/go-zones.txt
//   cd ../server && gofmt -w internal/zone/names_gen.go
