const root = path.resolve(import.meta.dirname, "..")
const zoneFile = process.argv[2]
if (!zoneFile) throw new Error("pass the Go zone list (see the header)")
const goZones = readFileSync(zoneFile, "utf8")
  .split("\n")
  .map((s) => s.trim())
  .filter((s) => s && !s.endsWith("/"))

// --- names_gen.go ----------------------------------------------------------------------

const valid = goZones.filter((z) => isValidZone(z)).sort()
const gmtName = (offMin: number) => {
  if (offMin === 0) return "GMT"
  const sign = offMin < 0 ? "-" : "+"
  const a = Math.abs(offMin)
  const h = Math.floor(a / 60)
  const m = a % 60
  return `GMT${sign}${h}${m ? `:${String(m).padStart(2, "0")}` : ""}`
}
// Short names that differ from the GMT form, by zone: [standard, daylight].
// Sampled every day of 2026, so both halves of a DST zone show up.
const special: Record<string, [string, string]> = {}
for (const z of valid) {
  let std: [number, string] | null = null
  let dst: [number, string] | null = null
  let differs = false
  for (let d = 0; d < 365; d += 1) {
    const t = Date.UTC(2026, 0, 1, 12) + d * 86_400_000
    const dt = DateTime.fromMillis(t, { zone: z })
    const name = dt.offsetNameShort ?? ""
    if (name !== gmtName(dt.offset)) differs = true
    if (!std || dt.offset < std[0]) std = [dt.offset, name]
    if (!dst || dt.offset > dst[0]) dst = [dt.offset, name]
  }
  if (differs && std && dst) special[z] = [std[1], dst[1]]
}
const goFile = [
  "// Code generated by testdata/gen/time.ts from Node's Intl (ICU) and Go's tzdata. DO NOT EDIT.",
  "",
  "package zone",
  "",
  "// names maps a lowercased zone name to its canonical spelling, for every zone",
  "// in Go's tzdata that Intl.DateTimeFormat accepts.",
  "var names = map[string]string{",
  ...valid.map((z) => `\t${JSON.stringify(z.toLowerCase())}: ${JSON.stringify(z)},`),
  "}",
  "",
  "// shortNames are luxon's offsetNameShort values that aren't the plain",
  '// "GMT+H[:MM]" form: [standard, daylight].',
  "var shortNames = map[string][2]string{",
  ...Object.entries(special).map(([z, [a, b]]) => `\t${JSON.stringify(z)}: {${JSON.stringify(a)}, ${JSON.stringify(b)}},`),
  "}",
  "",
].join("\n")
writeFileSync(path.join(root, "../internal/zone/names_gen.go"), goFile)
console.log(`wrote internal/zone/names_gen.go (${valid.length} zones, ${Object.keys(special).length} short names)`)

// --- cases -----------------------------------------------------------------------------

// timeError: whether the TS threw a TimeError (shown to the owner) or a plain
// Error (a bug path that callers rethrow).
type Result<T> = { ok: T } | { error: string; timeError: boolean }
function run<T>(fn: () => T): Result<T> {
  try {
    return { ok: fn() }
  } catch (e) {
    return { error: (e as Error).message, timeError: e instanceof TimeError }
  }
}

