// Offset transitions of a zone in [from, to): the instant the new offset starts.
function transitions(tz: string, from: number, to: number): number[] {
  const out: number[] = []
  let prev = DateTime.fromMillis(from, { zone: tz }).offset
  for (let t = from + 3600_000; t < to; t += 3600_000) {
    const o = DateTime.fromMillis(t, { zone: tz }).offset
    if (o !== prev) {
      // Find the exact minute.
      let lo = t - 3600_000
      let hi = t
      while (hi - lo > 60_000) {
        const mid = lo + Math.floor((hi - lo) / 120_000) * 60_000
        if (DateTime.fromMillis(mid, { zone: tz }).offset === prev) lo = mid
        else hi = mid
      }
      out.push(hi)
      prev = o
    }
  }
  return out
}

const instants: number[] = [NOW, Date.UTC(2026, 0, 1), Date.UTC(2026, 6, 1, 12, 34, 56), Date.UTC(2027, 1, 28, 23, 59), Date.UTC(2028, 1, 29, 3)]
const zoneCases = ZONES.map((tz) => {
  const ts = transitions(tz, Date.UTC(2026, 0, 1), Date.UTC(2027, 0, 1))
  const around = ts.flatMap((t) => [t - 3600_000, t - 60_000, t, t + 60_000, t + 3600_000, t + 5400_000])
  const ms = [...instants, ...around]
  // Wall times around each transition: every 15 minutes in the 3 hours around it.
  const locals = new Set<string>(["2026-11-11T09:00", "2026-03-08T02:30", "2026-11-01T01:30", "2026-01-01T00:00", "2026-12-31T23:59:59"])
  for (const t of ts) {
    const base = DateTime.fromMillis(t, { zone: tz })
    for (let m = -120; m <= 120; m += 15) locals.add(base.plus({ minutes: m }).toFormat("yyyy-LL-dd'T'HH:mm"))
    // The same wall time counted in floating time, which lands in gaps and overlaps.
    const f = DateTime.fromMillis(t, { zone: "utc" }).plus({ minutes: base.offset })
    for (let m = -90; m <= 90; m += 30) locals.add(f.plus({ minutes: m }).toFormat("yyyy-LL-dd'T'HH:mm"))
  }
  return {
    tz,
    transitions: ts,
    toUtc: [...locals].sort().map((local) => ({ local, ...run(() => localToUtc(local, tz)) })),
    fromUtc: ms.map((t) => ({
      ms: t,
      local: utcToLocal(t, tz),
      iso: utcToIso(t, tz),
      label: zoneLabel(tz, t),
      clock: formatClock(t, tz),
      date: formatDate(t, tz, NOW),
      when: formatWhen(t, tz, NOW),
      tomorrow: tomorrowAt(t, tz),
      tomorrow1830: tomorrowAt(t, tz, 18, 30),
      startOfDay: DateTime.fromMillis(t, { zone: tz }).startOf("day").toMillis(),
      nextDay: DateTime.fromMillis(t, { zone: tz }).startOf("day").plus({ days: 1 }).toMillis(),
      nextHour: DateTime.fromMillis(t, { zone: tz }).startOf("hour").plus({ hours: 1 }).toMillis(),
    })),
  }
})

